//! `BRepFill_Evolved::ContinuityOnOffsetEdge` (`BRepFill_Evolved.cxx:2452-2543`):
//! codes the regularities of the edges parallel to `CutVevo` that the left and
//! right parts of the volume share.
//!
//! The reference walks the profile wire and, for every profile vertex lying on
//! `z = 0` (`DistanceToOZ(V) <= BRepFill_Confusion()`), measures the continuity
//! between the two profile edges meeting at `V` (`BRepLProp::Continuity`,
//! `cxx:2483`) and stores it on the edge generated by `V` between the faces
//! generated by the two edges (`cxx:2493-2507`). A closed profile repeats the
//! test at the seam (`cxx:2513-2542`).

use occt_core::precision;

use crate::abs::Orientation;
use crate::brep_lib_continuity::set_stored_continuity;
use crate::brep_lprop;
use crate::brep_tool::BRepTool;
use crate::brep_tools_wire_explorer::WireExplorer;
use crate::shape::{Edge, Face, TopoShape};
use crate::topo_tools::is_same;
use crate::topopebrep::tool::adaptor::CurveAdaptor;

use super::evolved::BRepFillEvolved;
use super::side::{distance_to_oz, edge_vertices_oriented, FILL_CONFUSION};

/// `BRepLProp::Continuity(C1, C2, u1, u2)` (`BRepLProp.cxx:129-134`) with the
/// package defaults `Precision::Confusion()` / `Precision::Angular()`.
fn continuity_between(
    c1: &CurveAdaptor,
    u1: f64,
    c2: &CurveAdaptor,
    u2: f64,
    same_edge: bool,
) -> u8 {
    let Some(curve1) = c1.curve() else {
        return 0;
    };
    let Some(curve2) = c2.curve() else {
        return 0;
    };
    brep_lprop::continuity(
        curve1.as_ref(),
        Orientation::Forward,
        u1,
        (c1.first_parameter(), c1.last_parameter()),
        curve2.as_ref(),
        Orientation::Forward,
        u2,
        (c2.first_parameter(), c2.last_parameter()),
        same_edge,
        precision::CONFUSION,
        precision::ANGULAR,
    )
    .unwrap_or(0)
}

/// `B` in `ContinuityOnOffsetEdge`: the coded regularity goes on the edge
/// generated by the vertex between the two faces generated by each side.
fn code_continuity(
    my_map: &super::shape_map::ShapeMap<super::shape_map::ShapeMap<Vec<TopoShape>>>,
    v: &TopoShape,
    cur_e: &TopoShape,
    prec_e: &TopoShape,
    continuity: u8,
) {
    for (sp, inner) in my_map.iter() {
        if inner.find(v).is_none() || inner.find(cur_e).is_none() || inner.find(prec_e).is_none() {
            continue;
        }
        let Some(v_list) = inner.find(v) else {
            continue;
        };
        let Some(cur_list) = inner.find(cur_e) else {
            continue;
        };
        let Some(prec_list) = inner.find(prec_e) else {
            continue;
        };
        let (Some(edge), Some(cur_face), Some(prec_face)) =
            (v_list.first(), cur_list.first(), prec_list.first())
        else {
            continue;
        };
        let _ = sp;
        set_stored_continuity(&Edge(edge.clone()), &Face(cur_face.clone()), &Face(prec_face.clone()), continuity);
    }
}

impl BRepFillEvolved {
    /// `ContinuityOnOffsetEdge(WorkProf)` (`cxx:2452-2543`).
    ///
    /// The reference ignores its `WorkProf` argument and walks `myProfile`
    /// instead, so the port takes no argument either.
    pub fn continuity_on_offset_edge(&mut self) {
        let Some(profile) = self.my_profile.clone() else {
            return;
        };

        // `cxx:2462-2471`.
        let mut exp = WireExplorer::new();
        exp.init(&profile, None);
        let Some(first_e) = exp.current().cloned() else {
            return;
        };
        let mut prec_e: TopoShape = first_e.0.clone();
        let (vf, _v) = edge_vertices_oriented(&first_e);
        let Some(vf) = vf else {
            return;
        };
        if exp.more() {
            exp.next();
        }

        // `cxx:2472-2509`.
        let mut cur_e: TopoShape = prec_e.clone();
        while exp.more() {
            let Some(e) = exp.current() else {
                exp.next();
                continue;
            };
            cur_e = e.0.clone();
            let Some(v) = exp.current_vertex().cloned() else {
                prec_e = cur_e.clone();
                exp.next();
                continue;
            };

            if distance_to_oz(&v) <= FILL_CONFUSION {
                // `cxx:2481-2486`.
                let u1 = BRepTool::parameter_of_vertex(&cur_e, &v.0);
                let u2 = BRepTool::parameter_of_vertex(&prec_e, &v.0);
                let c1 = CurveAdaptor::of_edge(&Edge(cur_e.clone()));
                let c2 = CurveAdaptor::of_edge(&Edge(prec_e.clone()));
                let continuity = continuity_between(&c1, u1, &c2, u2, false);
                if continuity >= 1 {
                    code_continuity(&self.my_map, &v.0, &cur_e, &prec_e, continuity);
                }
            }
            prec_e = cur_e.clone();
            exp.next();
        }

        // `cxx:2511-2542`: the seam of a closed profile.
        let (_v, vl) = edge_vertices_oriented(&Edge(prec_e.clone()));
        if let Some(vl) = vl {
            if is_same(&vf.0, &vl.0) {
                let u1 = BRepTool::parameter_of_vertex(&cur_e, &vf.0);
                let u2 = BRepTool::parameter_of_vertex(&first_e.0, &vf.0);
                let c1 = CurveAdaptor::of_edge(&Edge(cur_e.clone()));
                let c2 = CurveAdaptor::of_edge(&first_e);
                let continuity = continuity_between(&c1, u1, &c2, u2, false);
                if continuity >= 1 {
                    code_continuity(&self.my_map, &vf.0, &cur_e, &first_e.0, continuity);
                }
            }
        }
    }
}
